 /** Does an action pattern such as "doc:*" match an action such as "doc:read"? See README.md. */
 export function matchAction(pattern: string, action: string): boolean {
-  throw new Error("not implemented");
+  if (pattern === "*") return true;
+  if (pattern.endsWith(":*")) {
+    const prefix = pattern.slice(0, -1);
+    return action.startsWith(prefix) && action.length > prefix.length;
+  }
+  return pattern === action;
 }

 /** Does a resource pattern with * and ** segments match a path? See README.md. */
 export function matchResource(pattern: string, resource: string): boolean {
-  throw new Error("not implemented");
+  const patternSegments = pattern.split("/").filter((s) => s !== "");
+  const resourceSegments = resource.split("/").filter((s) => s !== "");
+  return matchSegments(patternSegments, 0, resourceSegments, 0);
 }
+
+function matchSegments(pattern: string[], pi: number, resource: string[], ri: number): boolean {
+  if (pi === pattern.length) return ri === resource.length;
+  if (pattern[pi] === "**") {
+    for (let k = ri; k <= resource.length; k++) {
+      if (matchSegments(pattern, pi + 1, resource, k)) return true;
+    }
+    return false;
+  }
+  if (ri === resource.length) return false;
+  if (pattern[pi] !== "*" && pattern[pi] !== resource[ri]) return false;
+  return matchSegments(pattern, pi + 1, resource, ri + 1);
+}
